source:
source note sys.dataset(fields: [title, subtitle, status, summary, as_of, metric1_label, metric1_value, metric2_label, metric2_value, pick1_title, pick1_body, pick2_title, pick2_body])

state mode { shape: enum[brief, code, details], initial: .brief }
event code { mode: set(.code) }
event details { mode: set(.details) }
event back { mode: set(.brief) }

copy app { class: vocabulary, en: "Mail" }
copy sim { class: vocabulary, en: "Simulation" }
copy b_code { class: vocabulary, en: "Show code" }
copy b_details { class: vocabulary, en: "Details" }
copy b_back { class: vocabulary, en: "Back" }
copy req { class: vocabulary, en: "Bring the code and photo ID." }

view root Surface(pad: .tight) {
  Col(gap: 8) {
    Row(gap: 8, align: .center) {
      Icon(name: .mail, size: .row)
      TextCaption(text: copy.app, width: .fill)
      TextCaption(text: copy.sim)
    }
    when mode == .brief {
      Col(gap: 8) {
        TextTitle(text: note.title, width: .fill)
        TextCaption(text: note.metric2_value)
        TextBody(text: copy.req, width: .fill)
        Chip(text: copy.b_code, on_tap: code, tone: .primary)
        Chip(text: copy.b_details, on_tap: details)
      }
    }
    when mode == .code {
      Col(gap: 8) {
        TextCaption(text: note.title)
        TextTitle(text: note.metric1_value, width: .fill)
        TextBody(text: copy.req, width: .fill)
        Chip(text: copy.b_back, on_tap: back, tone: .primary)
      }
    }
    when mode == .details {
      Col(gap: 8) {
        TextCaption(text: note.title)
        TextBody(text: note.pick1_body, width: .fill)
        TextCaption(text: note.pick2_body)
        TextCaption(text: note.metric2_value)
        Chip(text: copy.b_back, on_tap: back, tone: .primary)
      }
    }
  }
}
